INSERT INTO reviews (review_id, review_text, rating, customer_id, customer_tier, product_id, lot_id, created_at) VALUES
('73532244556', 'QUÁ TỆ. RẤT TỆ Mua hàng của Unilever nhiều lần rồi, mà lần này gói hàng rất rất tệ, rất cẩu thả, còn tệ hơn hàng giả, hàng kém chất lượng. Dầu gội mà không bọc chống sốc, vòi pump còn bị bật ra chảy nước ra vỏ, cả hộp, không bao giờ mua lại.', 1, 'C01033', 'VIP', 'P09', 'L09-1', '2026-10-06T09:45:51+07:00'),
('73539733314', 'Hương thơm:ko có mùi gì Bao bì:bao bì ok  Đã sử dụng sau 1 tháng và quay lại đánh giá cho mấy bà khỏi tốn tiền: Tóm gọn là ko biết nó có công dụng gì luôn, tóc vẫn rụng như thường, bthg 3 ngày gội lần ko sao giờ ngày nào cx phải gội vì qua ngày thứ 2 là nó bết mà nó ngứa, trong khi da đầu tui ko phải loại nhiều dầu. Gội xong ko có mùi hương gì luôn, lại còn khô tóc mà ko mượt như các sunsilk dòng vàng vs đen ấy Nchung là lỡ mua nên ráng dùng cho hết chứ ko biết loại mới này ra có tác dụng gì luôn', 1, 'C03998', 'Regular', 'P09', 'L09-3', '2026-10-17T19:31:06+07:00'),
